import{at as e,it as t,st as n,vt as r}from"./chunks/framework.DQt_9H6f.js";import{n as i}from"./chunks/theme.Dd2C0RTo.js";var a=JSON.parse(`{"title":"Desktop App","description":"","frontmatter":{},"headers":[],"relativePath":"guide/desktop.md","filePath":"guide/desktop.md"}`),o=Object.assign({name:`guide/desktop.md`},{setup(a){return(a,o)=>(r(),t(`div`,null,[o[0]||=e(`<h1 id="desktop-app" tabindex="-1">Desktop App <a class="header-anchor" href="#desktop-app" aria-label="Permalink to “Desktop App”">​</a></h1><p>The TeXRA desktop app is a standalone application for researchers who want the full TeXRA workspace without installing VS Code. It shares your settings (<code>.texra/config.json</code> and <code>~/.texra</code>), credentials (<code>~/.texra/secrets/</code>), and task history with the VS Code extension and the CLI.</p><h2 id="availability-installation" tabindex="-1">Availability &amp; installation <a class="header-anchor" href="#availability-installation" aria-label="Permalink to “Availability &amp; installation”">​</a></h2><p>Public installers are coming soon.</p><table tabindex="0"><thead><tr><th>Platform</th><th>Artifact</th><th>Notes</th></tr></thead><tbody><tr><td>macOS</td><td>Universal <code>.dmg</code> and zip</td><td></td></tr><tr><td>Windows</td><td>x64 NSIS installer</td><td></td></tr><tr><td>Linux</td><td>x64 AppImage and <code>.deb</code></td><td>Manual install/update</td></tr></tbody></table><p>Once installers are published, download the build for your OS from the releases page, install it normally, and open your project folder. For LaTeX system dependencies, see <a href="/guide/installation.html">Installation</a>.</p><h2 id="first-run" tabindex="-1">First run <a class="header-anchor" href="#first-run" aria-label="Permalink to “First run”">​</a></h2>`,7),n(i,{steps:[{n:1,icon:`folder-open`,title:`Open a project`,desc:`Open your LaTeX or research project folder (File → Open Project Folder).`,chips:[{text:`project folder`,variant:`info`,icon:`folder-tree`}]},{n:2,icon:`key`,title:`Connect a model`,desc:`Sign in with ChatGPT/Grok or add API keys under Settings → Models (or a project .env).`,chips:[{text:`Models`,variant:`accent`},{text:`.env`,variant:`info`,icon:`file-code`}]},{n:3,icon:`gear`,title:`Review settings`,desc:`Check Agents, Plugins, Memory, LaTeX, and General (Approval & Git) in Settings.`,chips:[{text:`Settings`,variant:`accent`}]},{n:4,icon:`play`,title:`Start a task`,desc:`Ask TeXRA to tighten a section or check a proof and review the diff.`,chips:[{text:`Tasks`,variant:`success`,icon:`list-check`}]}]}),o[1]||=e(`<h3 id="shared-with-vs-code-and-cli" tabindex="-1">Shared with VS Code and CLI <a class="header-anchor" href="#shared-with-vs-code-and-cli" aria-label="Permalink to “Shared with VS Code and CLI”">​</a></h3><p>Opening the same project folder in the desktop app, VS Code extension, or CLI automatically shares:</p><ul><li>Project and user settings (<code>.texra/config.json</code> and <code>~/.texra</code>), plus <code>AGENTS.md</code></li><li>Saved API keys and subscription sign-ins (<code>~/.texra/secrets/</code>)</li><li>Task history and generated outputs</li></ul><h3 id="layout-and-projects" tabindex="-1">Layout and projects <a class="header-anchor" href="#layout-and-projects" aria-label="Permalink to “Layout and projects”">​</a></h3><p>The desktop app lets you arrange <strong>Agent</strong>, <strong>Files</strong>, <strong>Editor</strong>, <strong>PDF</strong>, <strong>Review</strong>, <strong>Terminal</strong>, and <strong>Logs</strong> in split panes whose layout persists across restarts and project switches.</p><p>Open projects appear in the <strong>Projects</strong> section of the left sidebar with a status dot; the active project&#39;s tasks appear in <strong>Task history</strong> below. Press <code>Cmd/Ctrl+K</code> to open <strong>Commands</strong> (or <strong>Switch Project</strong> for open projects), and use <strong>File → Open Recent</strong> to reopen closed projects.</p><h3 id="background-service" tabindex="-1">Background service <a class="header-anchor" href="#background-service" aria-label="Permalink to “Background service”">​</a></h3><p>On macOS and Linux, the desktop app runs tasks through the shared background TeXRA service (starting it automatically if needed). Tasks keep running if you close the app and can be followed from <code>texra chat</code> (<code>/tasks</code>) or a VS Code window open to the same project. If the service cannot start, the app falls back to running tasks locally.</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to “Logs”">​</a></h2><p>TeXRA writes desktop logs to <code>texra-desktop.log</code>. Open <strong>View → Show Logs</strong> (or run <strong>Show Logs</strong> from <strong>Commands</strong>) to inspect them in-app, or <strong>Help → Open Logs Folder</strong> to reveal the log directory.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to “Updates”">​</a></h2><p>Packaged builds check the public releases page on launch and notify you with a link when a newer version is available (updates are never downloaded or installed automatically). Set <code>TEXRA_NO_UPDATE_CHECK=1</code> to disable update checks.</p><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to “Related Docs”">​</a></h2><ul><li><a href="/guide/configuration.html">Configuration</a></li><li><a href="/guide/troubleshooting.html">Troubleshooting</a></li></ul>`,14)]))}});export{a as __pageData,o as default};